-- DuoMente MVP. Additive compatibility with the existing DuoMente project.
-- Apply once using Supabase migrations. Never run against an unrelated project.
create schema if not exists duomente_private;
revoke all on schema duomente_private from public,anon;
grant usage on schema duomente_private to authenticated;
create table if not exists public.organizations(id bigint generated always as identity primary key,name text not null,slug text not null unique,industry text not null,timezone text not null default 'America/Sao_Paulo',is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.organization_members(organization_id bigint references public.organizations not null,user_id uuid references auth.users not null,role text not null default 'viewer',created_at timestamptz not null default now(),primary key(organization_id,user_id));
alter table public.organization_members drop constraint if exists organization_members_role_check;
alter table public.organization_members add constraint organization_members_role_check check(role in ('owner','admin','manager','collaborator','viewer'));
alter table public.organization_members add column if not exists updated_at timestamptz not null default now();
alter table public.organization_members add column if not exists created_by uuid references auth.users;
alter table public.organizations add column if not exists created_by uuid references auth.users;
create index if not exists duomente_members_user_idx on public.organization_members(user_id,organization_id);
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create function duomente_private.member_role(p_org bigint) returns text language sql stable security definer set search_path='' as $$ select role from public.organization_members where organization_id=p_org and user_id=(select auth.uid()) $$;
revoke all on function duomente_private.member_role(bigint) from public,anon;
grant execute on function duomente_private.member_role(bigint) to authenticated;
create function duomente_private.touch_record() returns trigger language plpgsql set search_path='' as $$ begin if TG_OP='UPDATE' then if to_jsonb(old)->>'organization_id' is distinct from to_jsonb(new)->>'organization_id' then raise exception 'Organization is immutable'; end if; if to_jsonb(old)->>'created_by' is distinct from to_jsonb(new)->>'created_by' then raise exception 'Author is immutable';end if;new.created_at=old.created_at;end if; new.updated_at=now();return new;end $$;
create table public.business_profiles(id uuid primary key default gen_random_uuid(),organization_id bigint not null unique references public.organizations,details jsonb not null default '{}',created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.diagnostic_sessions(id uuid primary key default gen_random_uuid(),organization_id bigint not null references public.organizations,status text not null default 'in_progress' check(status in ('in_progress','paused','awaiting_approval','completed')),report jsonb,report_approved_at timestamptz,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),check(status<>'completed' or(report is not null and report_approved_at is not null)));
create unique index duomente_one_active_diagnostic on public.diagnostic_sessions(organization_id) where status<>'completed';
create table public.diagnostic_answers(id uuid primary key default gen_random_uuid(),organization_id bigint not null references public.organizations,session_id uuid not null,question_id text not null,answer text not null,unknown boolean not null default false,is_draft boolean not null default true,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,session_id) references public.diagnostic_sessions(organization_id,id),unique(session_id,question_id),check(not unknown or answer='N/D'));
create table public.evidence_items(id uuid primary key default gen_random_uuid(),organization_id bigint not null references public.organizations,description text not null,classification text not null check(classification in ('Fato validado','Dado declarado','Interpretação','Hipótese','Estimativa','Conflito','Dado ausente','Dado desatualizado')),source text,period text,responsible text,confidence text not null check(confidence in ('Baixa','Média','Alta')),assumptions text,storage_path text,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),check(classification<>'Fato validado' or length(trim(source))>0 and source is not null),check(classification<>'Estimativa' or length(trim(assumptions))>0 and assumptions is not null),check(storage_path is null or split_part(storage_path,'/',1)=organization_id::text));
create table public.global_objectives(id uuid primary key default gen_random_uuid(),organization_id bigint not null unique references public.organizations,description text not null,indicator text,current_value text,target_value text,due_date date,responsible text,areas text[] not null default '{}',confirmed boolean not null default false,confirmed_at timestamptz,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),check(not confirmed or confirmed_at is not null));
create table public.decisions(id uuid primary key default gen_random_uuid(),organization_id bigint not null references public.organizations,objective_id uuid,title text not null,question text not null,area text not null check(area in ('Marketing e Vendas','Finanças','Operações','Pessoas e RH')),status text not null default 'Identificada' check(status in ('Identificada','Em investigação','Aguardando dados','Pronta para decidir','Em execução','Em acompanhamento','Concluída','Cancelada')),responsible text,due_date date,details jsonb not null default '{}',created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,id),foreign key(organization_id,objective_id) references public.global_objectives(organization_id,id));
create table public.decision_evidence(id uuid primary key default gen_random_uuid(),organization_id bigint not null references public.organizations,decision_id uuid not null,evidence_id uuid not null,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,decision_id) references public.decisions(organization_id,id),foreign key(organization_id,evidence_id) references public.evidence_items(organization_id,id),unique(decision_id,evidence_id));
create table public.action_items(id uuid primary key default gen_random_uuid(),organization_id bigint not null references public.organizations,decision_id uuid,title text not null,responsible text,due_date date,status text not null default 'Pendente' check(status in ('Pendente','Em andamento','Concluída','Cancelada')),result text,created_by uuid not null default auth.uid() references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,decision_id) references public.decisions(organization_id,id));
create table if not exists public.agent_runs(id bigint generated always as identity primary key,organization_id bigint not null references public.organizations,agent_id bigint,module text not null,trigger_type text not null,status text not null default 'queued',input_payload jsonb not null default '{}',output_payload jsonb,error_message text,started_at timestamptz,finished_at timestamptz,created_at timestamptz not null default now());
alter table public.agent_runs alter column agent_id drop not null;
alter table public.agent_runs add column if not exists created_by uuid references auth.users;
alter table public.agent_runs add column if not exists updated_at timestamptz not null default now();
create table public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id bigint not null references public.organizations,table_name text not null,record_id text not null,operation text not null,old_data jsonb,new_data jsonb,created_by uuid references auth.users,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index duomente_audit_record on public.audit_logs(organization_id,record_id,created_at);
create function duomente_private.audit_record() returns trigger language plpgsql security definer set search_path='' as $$ declare row_data jsonb;begin row_data=case when TG_OP='DELETE' then to_jsonb(old) else to_jsonb(new) end;insert into public.audit_logs(organization_id,table_name,record_id,operation,old_data,new_data,created_by) values((row_data->>'organization_id')::bigint,TG_TABLE_NAME,coalesce(row_data->>'id',row_data->>'user_id'),TG_OP,case when TG_OP='INSERT' then null else to_jsonb(old) end,case when TG_OP='DELETE' then null else to_jsonb(new) end,auth.uid());return coalesce(new,old);end $$;
revoke all on function duomente_private.audit_record() from public,anon,authenticated;
revoke all on function duomente_private.touch_record() from public,anon;
alter table public.organizations enable row level security;
alter table public.organization_members enable row level security;
alter table public.profiles enable row level security;
create policy duomente_profiles_self on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy duomente_org_read on public.organizations for select to authenticated using(duomente_private.member_role(id) is not null);
create policy duomente_members_read on public.organization_members for select to authenticated using(duomente_private.member_role(organization_id) is not null);
-- Members are managed only through the checked RPC; no direct membership mutations.
grant select on public.organization_members,public.organizations to authenticated;
grant select,insert,update on public.profiles to authenticated;
do $$ declare t text;begin foreach t in array array['business_profiles','diagnostic_sessions','diagnostic_answers','evidence_items','global_objectives','decisions','decision_evidence','action_items'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('grant select,insert,update on public.%I to authenticated',t);
 execute format('create policy tenant_read on public.%I for select to authenticated using(duomente_private.member_role(organization_id) is not null)',t);
 execute format('create policy tenant_insert on public.%I for insert to authenticated with check(duomente_private.member_role(organization_id) in (''owner'',''admin'',''manager'',''collaborator'') and created_by=(select auth.uid()))',t);
 execute format('create policy tenant_update on public.%I for update to authenticated using(duomente_private.member_role(organization_id) in (''owner'',''admin'',''manager'',''collaborator'')) with check(duomente_private.member_role(organization_id) in (''owner'',''admin'',''manager'',''collaborator''))',t);
 execute format('create index %I on public.%I(organization_id)',t||'_tenant_idx',t);
 execute format('create trigger duomente_touch before update on public.%I for each row execute function duomente_private.touch_record()',t);
 execute format('create trigger duomente_audit after insert or update or delete on public.%I for each row execute function duomente_private.audit_record()',t);
 end loop;end $$;
alter table public.audit_logs enable row level security;
grant select on public.audit_logs to authenticated;
revoke insert,update,delete on public.audit_logs from authenticated,anon;
create policy duomente_audit_read on public.audit_logs for select to authenticated using(duomente_private.member_role(organization_id) is not null);
alter table public.agent_runs enable row level security;
grant select,insert,update on public.agent_runs to authenticated;
grant usage on sequence public.agent_runs_id_seq to authenticated;
create policy duomente_runs_insert on public.agent_runs for insert to authenticated with check(duomente_private.member_role(organization_id) in ('owner','admin','manager','collaborator') and created_by=(select auth.uid()) and agent_id is null and module='diretor' and trigger_type='manual');
create policy duomente_runs_update on public.agent_runs for update to authenticated using(duomente_private.member_role(organization_id) in ('owner','admin','manager','collaborator') and created_by=(select auth.uid()) and agent_id is null) with check(duomente_private.member_role(organization_id) in ('owner','admin','manager','collaborator') and created_by=(select auth.uid()) and agent_id is null);
create policy duomente_runs_read on public.agent_runs for select to authenticated using(duomente_private.member_role(organization_id) is not null);
create trigger duomente_touch before update on public.agent_runs for each row execute function duomente_private.touch_record();
create trigger duomente_audit after insert or update or delete on public.agent_runs for each row execute function duomente_private.audit_record();
create trigger duomente_members_audit after insert or update or delete on public.organization_members for each row execute function duomente_private.audit_record();
-- Narrow private privileged implementation; public API wrappers run as invoker.
create function duomente_private.create_org(p_name text,p_industry text) returns bigint language plpgsql security definer set search_path='' as $$ declare oid bigint;uid uuid:=auth.uid();begin if uid is null then raise exception 'Authentication required';end if;if length(trim(p_name))<2 or length(p_name)>200 or length(trim(p_industry))<2 then raise exception 'Invalid company';end if;insert into public.profiles(id) values(uid) on conflict do nothing;insert into public.organizations(name,industry,slug,created_by) values(trim(p_name),trim(p_industry),gen_random_uuid()::text,uid) returning id into oid;insert into public.organization_members(organization_id,user_id,role,created_by) values(oid,uid,'owner',uid);return oid;end $$;
revoke all on function duomente_private.create_org(text,text) from public,anon;
grant execute on function duomente_private.create_org(text,text) to authenticated;
create function public.create_duomente_organization(p_name text,p_industry text) returns bigint language sql security invoker set search_path='' as $$select duomente_private.create_org(p_name,p_industry)$$;
revoke all on function public.create_duomente_organization(text,text) from public,anon;
grant execute on function public.create_duomente_organization(text,text) to authenticated;
create function duomente_private.manage_member(p_org bigint,p_user uuid,p_role text) returns void language plpgsql security definer set search_path='' as $$ declare actor text;target text;begin actor=duomente_private.member_role(p_org);if auth.uid() is null or actor is null or actor not in ('owner','admin') then raise exception 'Admin required';end if;select role into target from public.organization_members where organization_id=p_org and user_id=p_user for update;if target='owner' then raise exception 'Owner cannot be changed by this operation';end if;if actor='admin' and (target='admin' or p_role='admin') then raise exception 'Only owner manages administrators';end if;if p_role='remove' then delete from public.organization_members where organization_id=p_org and user_id=p_user;elsif p_role in ('admin','manager','collaborator','viewer') then insert into public.organization_members(organization_id,user_id,role,created_by) values(p_org,p_user,p_role,auth.uid()) on conflict(organization_id,user_id) do update set role=excluded.role,updated_at=now();else raise exception 'Invalid role';end if;end $$;
revoke all on function duomente_private.manage_member(bigint,uuid,text) from public,anon;
grant execute on function duomente_private.manage_member(bigint,uuid,text) to authenticated;
create function public.manage_duomente_member(p_org bigint,p_user uuid,p_role text) returns void language sql security invoker set search_path='' as $$select duomente_private.manage_member(p_org,p_user,p_role)$$;
revoke all on function public.manage_duomente_member(bigint,uuid,text) from public,anon;
grant execute on function public.manage_duomente_member(bigint,uuid,text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('evidence','evidence',false,3145728,array['application/pdf','text/plain','text/csv','image/png','image/jpeg']);
create policy duomente_storage_read on storage.objects for select to authenticated using(bucket_id='evidence' and exists(select 1 from public.organization_members m where m.user_id=(select auth.uid()) and m.organization_id::text=(storage.foldername(name))[1]));
create policy duomente_storage_insert on storage.objects for insert to authenticated with check(bucket_id='evidence' and exists(select 1 from public.organization_members m where m.user_id=(select auth.uid()) and m.role in ('owner','admin','manager','collaborator') and m.organization_id::text=(storage.foldername(name))[1]));
create policy duomente_storage_delete on storage.objects for delete to authenticated using(bucket_id='evidence' and owner_id=(select auth.uid())::text and exists(select 1 from public.organization_members m where m.user_id=(select auth.uid()) and m.role in ('owner','admin','manager','collaborator') and m.organization_id::text=(storage.foldername(name))[1]));
